 781	const MSG_STATES: [string, string][] = [
 782	  ["working", "Working"], ["waiting", "Needs you"], ["done", "Done"],
 783	  ["celebrate", "Celebrate"], ["idle", "Idle"],
 784	];
 785	function initBubble() {
 786	  const changed = () => { emit("bubble-changed", null); };
 787	  const opacity = document.getElementById("opacity") as HTMLInputElement;
 788	  const editors = document.getElementById("msg-editors")!;
 789	
 790	  opacity.value = localStorage.getItem("ap_opacity") || "92";
 791	  opacity.oninput = () => {
 792	    localStorage.setItem("ap_opacity", opacity.value);
 793	    changed();
 794	    document.dispatchEvent(new CustomEvent("seg-changed", { detail: "ap_opacity" }));
 795	  };
 796	
 797	  const build = () => {
 798	    editors.innerHTML = "";
 799	    for (const [st, label] of MSG_STATES) {
 800	      const wrap = document.createElement("div");
 801	      wrap.className = "msg-editor";
 802	      const lbl = document.createElement("div");
 803	      lbl.className = "msg-label";
 804	      lbl.dataset.label = label;
 805	      lbl.textContent = t(label);
 806	      const ta = document.createElement("textarea");
 807	      const key = `ap_msg_all_${st}`;
 808	      ta.value = localStorage.getItem(key) || "";
 809	      ta.addEventListener("input", () => { localStorage.setItem(key, ta.value); changed(); });
 810	      wrap.appendChild(lbl);
 811	      wrap.appendChild(ta);
 812	      editors.appendChild(wrap);
 813	    }
 814	  };
 815	  build();
 816	
 817	  // System/custom source (segmented, saved by initSegs) + reset.
 818	  const customWrap = document.getElementById("msg-custom-wrap") as HTMLElement;
 819	  const syncSrc = () => { customWrap.style.display = (localStorage.getItem("ap_msg_src") || "system") === "custom" ? "" : "none"; };
 820	  syncSrc();
 821	  document.addEventListener("seg-changed", (e) => { if ((e as CustomEvent).detail === "ap_msg_src") syncSrc(); });
 822	  (document.getElementById("msg-reset") as HTMLButtonElement).onclick = () => {
 823	    for (const [st] of MSG_STATES) localStorage.removeItem(`ap_msg_all_${st}`);
 824	    build();
 825	    changed();
 826	  };
 827	
 828	  const idle = document.getElementById("idle") as HTMLInputElement;
 829	  idle.checked = localStorage.getItem("ap_idle") !== "0";
 830	  idle.onchange = () => { localStorage.setItem("ap_idle", idle.checked ? "1" : "0"); changed(); };
 831	}
 832	
 833	// ----------------------------------------------- instance controls ----
 834	function initPetControls() {
 835	  const size = document.getElementById("pet-size") as HTMLInputElement;
 836	  const roamMode = document.getElementById("roam-mode") as HTMLSelectElement;
 837	  const roamSpeed = document.getElementById("roam-speed") as HTMLInputElement;
 838	  const roamSpeedVal = document.getElementById("roam-speed-val") as HTMLSpanElement;
 839	  const wanderPauseMin = document.getElementById("wander-pause-min") as HTMLInputElement;
 840	  const wanderPauseMax = document.getElementById("wander-pause-max") as HTMLInputElement;
 841	
 842	  const updateSelected = (patch: Partial<Omit<PetInstance, "id">>) => {
 843	    const instance = currentPetInstance();
 844	    if (!instance) return;
 845	    persistDesktopPets(
 846	      updatePetInstance(currentPetStore(), instance.id, patch),
 847	      { syncWindows: false, instanceId: instance.id },
 848	    );
 849	  };
 850	
 851	  const sync = () => {
 852	    const instance = currentPetInstance();
 853	    size.disabled = !instance;
 854	    roamMode.disabled = !instance;
 855	    roamSpeed.disabled = !instance;
 856	    wanderPauseMin.disabled = !instance;
 857	    wanderPauseMax.disabled = !instance;
 858	    size.value = String(instance?.size ?? 100);
 859	    roamMode.value = instance?.roamMode ?? "wander";
 860	    roamSpeed.value = String(instance?.roamSpeed ?? 5);
 861	    roamSpeedVal.textContent = roamSpeed.value;
 862	    wanderPauseMin.value = String((instance?.wanderPauseMinMs ?? DEFAULT_WANDER_PAUSE_MIN_MS) / 1000);
 863	    wanderPauseMax.value = String((instance?.wanderPauseMaxMs ?? DEFAULT_WANDER_PAUSE_MAX_MS) / 1000);
 864	  };
 865	
 866	  size.oninput = () => updateSelected({ size: parseInt(size.value, 10) });
 867	  document.querySelectorAll<HTMLButtonElement>(".size-presets button").forEach((button) => {
 868	    button.onclick = () => {
 869	      size.value = button.dataset.size!;
 870	      updateSelected({ size: parseInt(size.value, 10) });
 871	    };
 872	  });
 873	  roamMode.onchange = () => updateSelected({ roamMode: roamMode.value as PetInstance["roamMode"] });
 874	  roamSpeed.oninput = () => updateSelected({ roamSpeed: parseInt(roamSpeed.value, 10) });
 875	  const saveWanderPause = () => {
 876	    updateSelected({
 877	      wanderPauseMinMs: Math.round(Number.parseFloat(wanderPauseMin.value) * 1000),
 878	      wanderPauseMaxMs: Math.round(Number.parseFloat(wanderPauseMax.value) * 1000),
 879	    });
 880	    sync();
 881	  };
 882	  wanderPauseMin.onchange = saveWanderPause;
 883	  wanderPauseMax.onchange = saveWanderPause;
 884	
 885	  sync();
 886	  void listen("pets-changed", sync);
 887	  void listen<{ instanceId: string }>("pet-instance-changed", (event) => {
 888	    if (currentPetInstance()?.id === event.payload.instanceId) sync();
 889	  });
