  5	
  6	/// <summary>
  7	/// 应用设置（对齐 Tauri 版 ap_theme/ap_opacity/ap_font_size/ap_font_family/ap_idle/
  8	/// ap_fx/ap_quick_bubbles/ap_quick_bubble_duration/ap_left_click_action/ap_roam/ap_lang）。
  9	/// 归一化与默认值在 Core（可单测），持久化由 IJsonStore 负责。
 10	/// </summary>
 11	public sealed record AppSettings(
 12	    string Theme,                    // system | light | dark
 13	    int BubbleOpacity,               // 0-100，默认 92
 14	    int FontSize,                    // 默认 12
 15	    string FontFamily,               // system | rounded | mono
 16	    bool ShowIdleChatter,            // ap_idle != "0"
 17	    bool BobAnimation,               // ap_fx == "1"
 18	    int PetSizePercent,              // 70-130，默认 100
 19	    int IdleActionIntervalSeconds,   // 待机动作轮播间隔 0-60s；0 = 关闭轮播（只播第一个动作）
 20	    string LeftClickAction,          // none | self | all
 21	    int QuickBubbleDurationSeconds,  // 1-10，默认 4
 22	    string[] QuickBubblePresets,
 23	    RoamConfig Roam,
 24	    AppLang Lang,
 25	    AiSettings Ai)                   // Phase 5：AI 设置（旧 JSON 无此字段 → 归一化给默认）
 26	{
 27	    public static AppSettings Defaults(AppLang detectedLang) => new(
 28	        Theme: "system",
 29	        BubbleOpacity: 92,
 30	        FontSize: 12,
 31	        FontFamily: "system",
 32	        ShowIdleChatter: true,
 33	        BobAnimation: false,
 34	        PetSizePercent: 100,
 35	        IdleActionIntervalSeconds: 12,
 36	        LeftClickAction: "none",
 37	        QuickBubbleDurationSeconds: 4,
 38	        QuickBubblePresets: ["辛苦了~", "摸摸头", "加油！", "休息一下吧", "盯——", "(*´∀`*)"],
 39	        Roam: new RoamConfig(true, RoamMode.Wander, 5, 1200, 3500),
 40	        Lang: detectedLang,
 41	        Ai: AiSettings.Defaults);
 42	
 43	    public static AppSettings Normalize(AppSettings raw)
 44	    {
 45	        var theme = raw.Theme switch { "light" => "light", "dark" => "dark", _ => "system" };
 46	        var fontFamily = raw.FontFamily switch { "rounded" => "rounded", "mono" => "mono", _ => "system" };
 47	        var clickAction = raw.LeftClickAction switch { "self" => "self", "all" => "all", _ => "none" };
 48	        var roam = RoamConfigOps.Normalize(raw.Roam);
 49	        return new AppSettings(
 50	            theme,
 51	            Math.Clamp(raw.BubbleOpacity, 0, 100),
 52	            Math.Clamp(raw.FontSize, 8, 24),
 53	            fontFamily,
 54	            raw.ShowIdleChatter,
 55	            raw.BobAnimation,
 56	            Math.Clamp(raw.PetSizePercent, 70, 130),
 57	            Math.Clamp(raw.IdleActionIntervalSeconds, 0, 60),
 58	            clickAction,
 59	            Math.Clamp(raw.QuickBubbleDurationSeconds, 1, 10),
 60	            raw.QuickBubblePresets ?? [],
 61	            roam with { Speed = roam.Speed },
 62	            raw.Lang,
 63	            AiSettings.Normalize(raw.Ai));
 64	    }
 65	}

