  2	using DesktopPet.Core.Slicing;
  3	using SixLabors.ImageSharp;
  4	using SixLabors.ImageSharp.PixelFormats;
  5	
  6	namespace DesktopPet.Core.Rendering;
  7	
  8	/// <summary>
  9	/// 解码后的精灵图 + alpha-gutter 切片。切片结果预裁为每帧独立位图（对比 TS 版
 10	/// 每帧从大图裁剪是净优化，迁移计划 §6.2）；掩码缓存供 alpha hitTest。
 11	/// </summary>
 12	public sealed class SpriteSheet
 13	{
 14	    public required string SourceName { get; init; }
 15	    public required int SourceWidth { get; init; }
 16	    public required int SourceHeight { get; init; }
 17	    public required IReadOnlyList<IReadOnlyList<SpriteFrame>> Clips { get; init; }
 18	    public required IReadOnlyList<int> ClipMaxWidths { get; init; }
 19	
 20	    public bool IsEmpty => Clips.Count == 0;
 21	
 22	    /// <summary>解码（ImageSharp：PNG/WebP）→ 切片 → 预裁剪帧。失败返回 null（调用方回退占位）。</summary>
 23	    public static SpriteSheet? Decode(byte[] bytes, string sourceName)
 24	    {
 25	        try
 26	        {
 27	            using var image = Image.Load<Rgba32>(bytes);
 28	            var width = image.Width;
 29	            var height = image.Height;
 30	            if (width <= 0 || height <= 0) return null;
 31	
 32	            var rgba = new byte[width * height * 4];
 33	            image.CopyPixelDataTo(rgba);
 34	            var clips = SpriteSlicer.Slice(rgba, width, height);
 35	            if (clips.Count == 0) return null;
 36	
 37	            var frames = clips.Select(row => (IReadOnlyList<SpriteFrame>)row
 38	                .Select(rect => CropFrame(rgba, width, rect))
 39	                .ToList()).ToList();
 40	            var maxWidths = frames
 41	                .Select(row => row.Count > 0 ? row.Max(f => f.Width) : 0)
 42	                .ToList();
 43	
 44	            return new SpriteSheet
 45	            {
 46	                SourceName = sourceName,
 47	                SourceWidth = width,
 48	                SourceHeight = height,
 49	                Clips = frames,
 50	                ClipMaxWidths = maxWidths,
 51	            };
 52	        }
 53	        catch (Exception)
 54	        {
 55	            return null; // 解码失败（非图片/损坏）→ 调用方回退占位精灵
 56	        }
 57	    }
 58	
 59	    private static SpriteFrame CropFrame(byte[] source, int sourceWidth, SliceRect rect)
 60	    {
 61	        var rgba = new byte[rect.W * rect.H * 4];
 62	        var mask = new byte[rect.W * rect.H];
 63	        for (var y = 0; y < rect.H; y++)
 64	        {
 65	            var srcRow = (rect.Y + y) * sourceWidth + rect.X;
 66	            var dstRow = y * rect.W;
 67	            for (var x = 0; x < rect.W; x++)
 68	            {
 69	                var src = (srcRow + x) * 4;
 70	                var dst = (dstRow + x) * 4;
 71	                rgba[dst] = source[src];
 72	                rgba[dst + 1] = source[src + 1];
 73	                rgba[dst + 2] = source[src + 2];
 74	                rgba[dst + 3] = source[src + 3];
 75	                if (source[src + 3] > SpriteSlicer.AlphaThreshold) mask[dstRow + x] = 1;
 76	            }
 77	        }
 78	        return new SpriteFrame(rgba, mask, rect.W, rect.H, rect.X, rect.Y);
 79	    }
 80	}

