578	    /// <summary>
579	    /// 消息级拖拽（绕过 WPF 事件系统——WPF 会合并丢弃捕获后的 WM_MOUSEMOVE，
580	    /// 且事件分发有额外开销）。语义对齐 windows/src/window-drag.ts：
581	    /// alpha hitTest 命中才按下；4px 阈值区分点击/拖拽；直接 SetWindowPos。
582	    /// </summary>
583	    private void OnRawLeftDown(nint lParam)
584	    {
585	        if (_dragging || _pressed) return;
586	        var client = ClientPointOfMessage(lParam);
587	        if (!HitTestSprite(client)) return;
588	
589	        _pressed = true;
590	        _pressPoint = client;
591	        _pressMessageTime = NativeMethods.MessageTime();
592	        _pressTickMs = Environment.TickCount64;
593	        var cursor = NativeMethods.CursorPosition();
594	        var windowPos = PhysicalPosition();
595	        _grabOffset = (cursor.X - windowPos.X, cursor.Y - windowPos.Y);
596	        CaptureMouse();
597	        _roamEngine.BeginManualDrag(); // 采样起点 + 取消抛掷（对齐 beginManualDrag）
598	        BenchTrace($"raw down hit at {client.X},{client.Y}");
599	    }
