593	        var cursor = NativeMethods.CursorPosition();
594	        var windowPos = PhysicalPosition();
595	        _grabOffset = (cursor.X - windowPos.X, cursor.Y - windowPos.Y);
596	        CaptureMouse();
597	        _roamEngine.BeginManualDrag(); // 采样起点 + 取消抛掷（对齐 beginManualDrag）
598	        BenchTrace($"raw down hit at {client.X},{client.Y}");
599	    }
600	
601	    private void OnRawMove(nint lParam)
602	    {
603	        if (!_pressed) return;
604	        var client = ClientPointOfMessage(lParam);
605	        if (!_dragging && MovedBeyondThreshold(client))
606	        {
607	            _dragging = true;
608	            BenchTrace("raw drag started");
609	        }
610	        if (!_dragging) return;
611	
612	        var cursor = NativeMethods.CursorPosition();
613	        var targetX = cursor.X - _grabOffset.X;
614	        var targetY = cursor.Y - _grabOffset.Y;
615	        var messageTime = NativeMethods.MessageTime();
616	        var sw = Stopwatch.StartNew();
617	        _roamEngine.MoveManualDrag(new RoamPoint(targetX, targetY)); // 移动 + 物理采样
618	        sw.Stop();
619	        _processingLatencyMs.Add(sw.Elapsed.TotalMilliseconds);
620	        // 端到端：消息生成 → 窗口位移完成（含系统输入管线/队列等待）
621	        _endToEndLatencyMs.Add(Math.Max(0, Environment.TickCount64 - messageTime));
622	    }
623	
624	    private void OnRawLeftUp()
625	    {
626	        if (!_pressed) return;
627	        _pressed = false;
628	        ReleaseMouseCapture();
629	
630	        if (_dragging)
631	        {
632	            _dragging = false;
633	            _roamEngine.FinishManualDrag(); // releasePending → 引擎 tick 抛掷/下落
634	            var (x, y) = PhysicalPosition();
635	            _onDragFinished(this, x, y);
636	            BenchTrace($"raw drag finished at {x},{y}");
637	        }
638	        else if (Environment.TickCount64 - _pressTickMs <= 280)
639	        {
640	            // 未超阈值 = 点击（对齐 WindowDragController clickMaxMs + onClick）
641	            OnPetClick();
642	        }
643	    }
644	
645	    /// <summary>点击宠物（对齐 onPetClick：LEFT_CLICK_KEY none/self/all）。</summary>
646	    private void OnPetClick()
647	    {
648	        if (_clickAction == "none") return;
649	        var text = RandomPreset();
650	        if (text is null) return;
651	        if (_clickAction == "self")
652	        {
653	            _quickBubble.Show(text, QuickBubbleDurationMs);
654	            RenderBubble();
655	        }
656	        else
657	        {
658	            _broadcastQuickBubble?.Invoke(text);
659	        }
660	    }
661	
662	    /// <summary>WM 消息 lParam 的客户区坐标（物理像素，低 16 位 x，高 16 位 y）。</summary>
663	    private static (int X, int Y) ClientPointOfMessage(nint lParam)
664	    {
665	        var raw = lParam.ToInt64();
666	        var x = (short)(raw & 0xFFFF);
667	        var y = (short)((raw >> 16) & 0xFFFF);
668	        return (x, y);
669	    }
