671	    private void UpdateTimerState()
672	    {
673	        if (!IsVisible || _desktopInteractionSuspended)
674	        {
675	            _animationTimer.Stop();
676	            _roamTimer.Stop();
677	            _renderTimer.Stop();
678	            return;
679	        }
680	
681	        RestartAnimation();
682	        _roamTimer.Start();
683	        _renderTimer.Start();
684	    }
