695	    private void AdvanceFrame()
696	    {
697	        if (!_animationEnabled || !IsVisible) return;
698	        if (_renderer is not null)
699	        {
700	            // 待机轮播节奏：idle 播放列表激活中且超过间隔 → 换一个动作行（窗口层计时）
701	            if (_renderer.IsIdleCycling && _idleActionIntervalSeconds > 0)
702	            {
703	                var now = _roamClock.NowMs();
704	                if (now - _lastIdleSwitchMs >= _idleActionIntervalSeconds * 1000L)
705	                {
706	                    _renderer.AdvanceIdleClip();
707	                    _lastIdleSwitchMs = now;
708	                }
709	            }
710	            _renderer.AdvanceFrame();
711	            DrawFrame(0);
712	            var fps = _renderer.Fps;
713	            var target = TimeSpan.FromMilliseconds(1000.0 / fps);
714	            if (Math.Abs(_animationTimer.Interval.TotalMilliseconds - target.TotalMilliseconds) > 1)
715	            {
716	                _animationTimer.Interval = target; // 帧率随状态行变化（fps 3-8）
717	            }
718	        }
719	        else
720	        {
721	            _frameIndex++;
722	            DrawFrame(_frameIndex % PlaceholderPet.Frames.Count);
723	        }
724	    }
