  3	namespace DesktopPet.Core.Rendering;
  4	
  5	/// <summary>预裁剪帧：RGBA 像素 + alpha 掩码（hitTest O(1)），切片时一次性生成。</summary>
  6	/// <param name="RectX">帧在源图中的 x（网格线绘制用）。</param>
  7	/// <param name="RectY">帧在源图中的 y。</param>
  8	public sealed record SpriteFrame(byte[] Rgba, byte[] Mask, int Width, int Height, int RectX = 0, int RectY = 0);
  9	
 10	/// <summary>idle 播放列表配置（对齐 pet.ts 的 ap_idle_clips / ap_idle_interval / ap_idle_mode）。</summary>
 11	public sealed record IdlePlaylistOptions(IReadOnlyList<int> Clips, double IntervalMs, bool Random);
 12	
 13	/// <summary>
 14	/// 精灵渲染器：1:1 移植 windows/src/pet.ts 的 Pet 类绘制语义 —— 动画行
 15	/// （overrideRow ?? idleRow ?? moodRow）、行内帧循环、每行最宽帧缩放
 16	/// （per-CLIP 缩放，帧间不抖动）、anchored bottom-center 整数缩放、headroom
 17	/// 与 spriteRect（气泡定位用）。渲染循环由窗口驱动（DispatcherTimer），
 18	/// 帧绘制为 WriteableBitmap 直写。
 19	/// </summary>
 20	public sealed class PetRenderer
 21	{
 22	    private readonly SpriteSheet _sheet;
 23	    private IdlePlaylistOptions? _idle;   // 可变：轮播间隔运行中可更新（设置页即时生效）
 24	    private int _row;                 // 情绪行（setState）
 25	    private int? _overrideRow;        // 漫游/交互覆盖行（setRow/clearRow）
 26	    private int? _idleRow;            // idle playlist 当前行
 27	    private int _idleIndex;
 28	    private int _frame;
 29	    private double _fps = 3;
 30	    private int _lastDrawnRow = -1;
 31	
 32	    /// <summary>精灵缩放百分比（设置页 70-130%，1.0 = 填满缓冲）。</summary>
 33	    private double _sizePercent = 1.0;
 34	    /// <summary>待机浮动（bob）：独立相位计数器，行切换不跳变。</summary>
 35	    private bool _bobEnabled;
 36	    private int _bobPhase;
 37	
 38	    /// <summary>设置精灵尺寸百分比（0.7-1.3，越界钳制）。</summary>
 39	    public void SetSizePercent(double percent) => _sizePercent = Math.Clamp(percent, 0.7, 1.3);
 40	
 41	    /// <summary>开关待机上下浮动（设置页 ap_fx）。</summary>
 42	    public void SetBob(bool enabled) => _bobEnabled = enabled;
 43	
 44	    /// <summary>idle 播放列表激活中（窗口驱动轮播节奏时用）。</summary>
 45	    public bool IsIdleCycling => _idle is { Clips.Count: > 0 } && _idleRow is not null;
 46	
 47	    /// <summary>运行中更新轮播间隔（设置页拖动即时生效，无需重建渲染器）。</summary>
 48	    public void SetIdleIntervalMs(double intervalMs)
 49	    {
 50	        if (_idle is null) return;
 51	        _idle = _idle with { IntervalMs = Math.Max(0, intervalMs) };
 52	    }
 53	
 54	    public double Fps => _fps;
 55	    public int ActiveRow => _overrideRow ?? _idleRow ?? _row;
 56	
 57	    /// <summary>精灵上方留白比例（气泡锚点，对齐 pet.ts headroom）。</summary>
 58	    public double Headroom { get; private set; }
 59	
 60	    /// <summary>最近绘制的精灵矩形（buffer 像素）。</summary>
 61	    public (int X, int Y, int W, int H) SpriteRect { get; private set; }
 62	
 63	    private double _lastScale = 1;
 64	
 65	    public PetRenderer(SpriteSheet sheet, IdlePlaylistOptions? idleOptions = null)
 66	    {
 67	        _sheet = sheet;
 68	        _idle = idleOptions;
 69	    }
 70	
 71	    /// <summary>切到状态行 + 帧率；idle 时进入播放列表（对齐 setState）。</summary>
 72	    public void SetState(string state, int? boundRow = null)
 73	    {
 74	        _fps = StateMapping.FpsFor(state);
