 3	/// <summary>
 4	/// 1:1 移植自 windows/src/pet.ts 的 STATE_ROW / STATE_FPS 与 setState 行覆盖语义。
 5	/// 行号对应 spritesheet 布局：0 Idle, 1 RunRight, 2 RunLeft, 3 Waving,
 6	/// 4 Jumping, 5 Failed, 6 Waiting, 7 Running, 8 Review。
 7	/// </summary>
 8	public static class StateMapping
 9	{
10	    private static readonly IReadOnlyDictionary<string, int> StateRow = new Dictionary<string, int>
11	    {
12	        ["idle"] = 0,
13	        ["registered"] = 0,
14	        ["working"] = 7,
15	        ["waiting"] = 6,
16	        ["done"] = 3,       // waving goodbye to the finished task
17	        ["celebrate"] = 4,  // jumping, the 3s burst when all work completes
18	    };
19	
20	    private static readonly IReadOnlyDictionary<string, double> StateFps = new Dictionary<string, double>
21	    {
22	        ["working"] = 8,
23	        ["celebrate"] = 8,
24	        ["waiting"] = 4,
25	        ["done"] = 3,
26	        ["idle"] = 3,
27	        ["registered"] = 3,
28	    };
29	
30	    /// <summary>state → 行号；未知 state 回退 0。boundRow 为设置页绑定覆盖（TS ap_bind_*）。</summary>
31	    public static int RowFor(string state, int? boundRow = null)
32	    {
33	        if (boundRow is >= 0) return boundRow.Value;
34	        return StateRow.TryGetValue(state, out var row) ? row : 0;
35	    }
36	
37	    public static double FpsFor(string state)
38	        => StateFps.TryGetValue(state, out var fps) ? fps : 3;
39	}

