120	    private RoamPoint Climb(RoamEnvironment env, RoamPoint pos, IRoamPet? pet)
121	    {
122	        if (env.Windows.Count == 0)
123	        {
124	            _climbDirection = 0;
125	            return FallbackWander(env, pos, pet);
126	        }
127	        if (_clock.NowMs() < _restUntil) return pos;
128	
129	        var surface = FindSurfaceBelow(pos, env);
130	        if (!surface.IsWindow || !IsStandingOnSurface(pos, surface, env.WorkArea))
131	        {
132	            _climbDirection = 0;
133	            var target = NearestClimbTarget(pos, env);
134	            return target is { } t ? MoveToward(t, pos, env.WorkArea, pet) : FallbackWander(env, pos, pet);
135	        }
136	
137	        var support = SurfaceSupportRange(surface.Rect, env.WorkArea);
138	        if (support is null)
139	        {
140	            _climbDirection = 0;
141	            return FallbackWander(env, pos, pet);
142	        }
143	        var standY = ClimbTopY(surface.Rect, env.WorkArea);
144	
145	        var dir = _climbDirection != 0 ? _climbDirection : (_random() < 0.5 ? -1 : 1);
146	        _climbDirection = dir;
147	        var step = RoamConfigOps.PxPerSec(_configSource().Speed) * RoamConstants.DtSec;
148	        var nextX = pos.X + dir * step;
149	        var onEdge = nextX < support.Value.Left - 2 || nextX > support.Value.Right + 2;
150	
151	        if (onEdge)
152	        {
153	            _restUntil = _clock.NowMs() + RoamConstants.IdleMsMin +
154	                         _random() * (RoamConstants.IdleMsMax - RoamConstants.IdleMsMin);
155	            _climbDirection = dir == 1 ? -1 : 1;
156	            pet?.ClearRow();
157	            return new RoamPoint(
158	                Math.Max(support.Value.Left, Math.Min(support.Value.Right, pos.X)),
159	                standY);
160	        }
161	
162	        var next = RoamConfigOps.ClampToBounds(new RoamPoint(nextX, standY), env.WorkArea);
163	        pet?.SetRow(dir > 0 ? RowRight : RowLeft);
164	        return next;
165	    }
