462	            VerticalAlignment = VerticalAlignment.Center,
463	        };
464	        visibleToggle.Checked += (_, _) => UpdateInstance(instance.Id, new PetInstancePatch { Visible = true });
465	        visibleToggle.Unchecked += (_, _) => UpdateInstance(instance.Id, new PetInstancePatch { Visible = false });
466	        controls.Children.Add(visibleToggle);
