490	        personaCombo.Items.Add("跟随全局");
491	        foreach (var personaItem in allPersonas) personaCombo.Items.Add(personaItem.Name);
492	        var currentIndex = instance.PersonaId is null ? 0
493	            : allPersonas.Select((item, index) => (item, index))
494	                .Where(x => x.item.Id == instance.PersonaId)
495	                .Select(x => x.index + 1)
496	                .DefaultIfEmpty(0)
497	                .First();
498	        personaCombo.SelectedIndex = currentIndex;
499	        personaCombo.SelectionChanged += (_, _) =>
500	        {
501	            if (personaCombo.SelectedIndex <= 0)
502	            {
503	                UpdateInstance(instance.Id, new PetInstancePatch { PersonaId = null });
504	            }
505	            else
506	            {
507	                var picked = allPersonas[personaCombo.SelectedIndex - 1];
508	                UpdateInstance(instance.Id, new PetInstancePatch { PersonaId = picked.Id });
509	            }
510	        };
