512	        controls.Children.Add(persona);
513	
514	        Grid.SetRow(controls, 1);
515	        details.Children.Add(controls);
516	        Grid.SetColumn(details, 1);
517	        grid.Children.Add(details);
518	        return grid;
519	    }
