521	    private void UpdateInstance(string id, PetInstancePatch patch)
522	    {
523	        var store = _store.LoadPetStore() ?? PetStoreModel.EmptyPetStore();
524	        store = PetStoreModel.UpdatePetInstance(store, id, patch);
525	        _store.SavePetStore(store);
526	        _manager.Reconcile(store, _manager.GloballyVisible);
527	    }
