530	    {
531	        var store = _store.LoadPetStore() ?? PetStoreModel.EmptyPetStore();
532	        store = PetStoreModel.RemovePetInstance(store, id);
533	        _store.SavePetStore(store);
534	        _manager.Reconcile(store, _manager.GloballyVisible);
535	        ShowPage("pets");
