538	    private async Task ImportPetAsync()
539	    {
540	        var dialog = new Microsoft.Win32.OpenFileDialog
541	        {
542	            Filter = "精灵图 (PNG/WebP)|*.png;*.webp",
543	            Title = "导入宠物精灵图",
544	        };
545	        if (dialog.ShowDialog(this) != true) return;
546	        try
547	        {
548	            var bytes = await File.ReadAllBytesAsync(dialog.FileName);
549	            var sheet = SpriteSheet.Decode(bytes, Path.GetFileName(dialog.FileName));
550	            if (sheet is null)
551	            {
552	                MessageBox.Show(this, "无法解析精灵图（需要带透明通道的 PNG/WebP）", "DesktopPet");
553	                return;
554	            }
555	            var preview = new SpritePreviewWindow(sheet, bytes, Path.GetFileNameWithoutExtension(dialog.FileName))
556	            {
557	                Owner = this,
558	            };
559	            if (preview.ShowDialog() == true)
560	            {
561	                var (payload, name) = preview.ImportPayload;
562	                _manager.ImportSprite(payload, name);
563	                ShowPage("pets");
564	            }
565	        }
566	        catch (Exception ex)
567	        {
568	            MessageBox.Show(this, $"导入失败：{ex.Message}", "DesktopPet");
569	        }
570	    }
