184	    public static PetStore? ParsePetStore(JsonElement value)
185	    {
186	        if (value.ValueKind != JsonValueKind.Object) return null;
187	        if (!value.TryGetProperty("version", out var versionEl) ||
188	            versionEl.ValueKind != JsonValueKind.Number ||
189	            versionEl.GetInt32() != StoreVersion ||
190	            !value.TryGetProperty("instances", out var instancesEl) ||
191	            instancesEl.ValueKind != JsonValueKind.Array)
192	        {
193	            return null;
194	        }
195	
196	        var ids = new HashSet<string>();
197	        var instances = new List<PetInstance>();
198	        foreach (var element in instancesEl.EnumerateArray())
199	        {
200	            var normalized = Normalize(RawFromJson(element));
201	            if (normalized is null || !ids.Add(normalized.Id)) continue;
202	            instances.Add(normalized);
203	        }
204	
205	        var selectedId = value.TryGetProperty("selectedId", out var selectedEl) &&
206	                         selectedEl.ValueKind == JsonValueKind.String &&
207	                         ids.Contains(selectedEl.GetString()!)
208	            ? selectedEl.GetString()
209	            : instances.Count > 0 ? instances[0].Id : null;
210	
211	        return new PetStore { Version = StoreVersion, SelectedId = selectedId, Instances = instances };
212	    }
