237	    public static PetStore CreatePetInstance(PetStore store, PetInstance instance)
238	    {
239	        if (store.Instances.Any(candidate => candidate.Id == instance.Id))
240	        {
241	            throw new InvalidOperationException($"duplicate pet instance id: {instance.Id}");
242	        }
243	        var normalized = Normalize(RawPetInstance.FromInstance(instance))
244	            ?? throw new InvalidOperationException("invalid pet instance");
245	        return new PetStore
246	        {
247	            Version = StoreVersion,
248	            SelectedId = normalized.Id,
249	            Instances = [.. store.Instances, normalized],
250	        };
251	    }
252	
253	    public static PetStore UpdatePetInstance(PetStore store, string id, PetInstancePatch patch)
254	    {
255	        var index = store.Instances
256	            .Select((candidate, i) => (candidate, i))
257	            .FirstOrDefault(x => x.candidate.Id == id);
258	        if (index.candidate is null) throw new InvalidOperationException($"unknown pet instance id: {id}");
259	
260	        var current = index.candidate;
261	        var merged = new RawPetInstance
262	        {
263	            Id = current.Id,
264	            Name = patch.Name ?? current.Name,
265	            SpriteSlug = patch.SpriteSlug ?? current.SpriteSlug,
266	            Visible = patch.Visible ?? current.Visible,
267	            Size = patch.Size ?? current.Size,
268	            RoamEnabled = patch.RoamEnabled ?? current.RoamEnabled,
269	            RoamMode = patch.RoamMode ?? current.RoamMode,
270	            RoamSpeed = patch.RoamSpeed ?? current.RoamSpeed,
271	            WanderPauseMinMs = patch.WanderPauseMinMs ?? current.WanderPauseMinMs,
272	            WanderPauseMaxMs = patch.WanderPauseMaxMs ?? current.WanderPauseMaxMs,
273	            ReactsToActivity = patch.ReactsToActivity ?? current.ReactsToActivity,
274	            PersonaId = patch.PersonaId ?? current.PersonaId,
275	        };
276	        var updated = Normalize(merged) ?? throw new InvalidOperationException("invalid pet instance update");
277	        var instances = store.Instances.ToList();
278	        instances[index.i] = updated;
279	        return new PetStore { Version = StoreVersion, SelectedId = store.SelectedId, Instances = instances };
280	    }
281	
282	    public static PetStore RemovePetInstance(PetStore store, string id)
283	    {
284	        var instances = store.Instances.Where(instance => instance.Id != id).ToList();
285	        if (instances.Count == store.Instances.Count) return store;
286	        return new PetStore
287	        {
288	            Version = StoreVersion,
289	            SelectedId = store.SelectedId == id ? instances.FirstOrDefault()?.Id ?? null : store.SelectedId,
290	            Instances = instances,
291	        };
292	    }
293	
294	    public static PetStore SelectPetInstance(PetStore store, string? id)
295	    {
296	        if (id is not null && !store.Instances.Any(instance => instance.Id == id))
297	        {
298	            throw new InvalidOperationException($"unknown pet instance id: {id}");
299	        }
300	        return new PetStore { Version = StoreVersion, SelectedId = id, Instances = store.Instances };
301	    }
