  1	using System.Text.Json;
  2	using DesktopPet.Core.Care;
  3	using DesktopPet.Core.Pets;
  4	
  5	namespace DesktopPet.Core.Storage;
  6	
  7	/// <summary>迁移结果。</summary>
  8	public sealed record TauriMigrationResult(
  9	    PetStore Store,
 10	    Dictionary<string, CareState> Care,
 11	    bool HadData);
 12	
 13	/// <summary>
 14	/// Tauri 版 localStorage 数据一次性迁移工具（迁移计划 Phase 3：含 ap_care_* 养成状态）。
 15	/// 输入为导出的 localStorage 键值 JSON（键 → 字符串值）：
 16	/// {
 17	///   "desktoppet.petSlug": "\"cat\"",          // legacy 选中精灵
 18	///   "ap_pet_instances": "{...}",              // PetStore（新版实例优先）
 19	///   "ap_care": "{\"cat\":{...}}"              // 每精灵养成状态
 20	/// }
 21	/// 导出方式：Tauri 版开发控制台执行
 22	/// localStorage 相关键 JSON.stringify 后保存为 tauri-export.json。
 23	/// </summary>
 24	public static class TauriMigration
 25	{
 26	    public static TauriMigrationResult Migrate(JsonElement export, DateTime now)
 27	    {
 28	        var petStoreRaw = ReadString(export, "ap_pet_instances");
 29	        var legacySlugRaw = ReadString(export, "desktoppet.petSlug");
 30	        var careRaw = ReadString(export, "ap_care");
 31	
 32	        var care = ParseCare(careRaw);
 33	        var hadData = false;
 34	
 35	        // 1. 宠物实例：新版实例 store 优先；否则 legacy slug → 默认实例
 36	        PetStore? store = null;
 37	        if (petStoreRaw is not null)
 38	        {
 39	            try
 40	            {
 41	                using var doc = JsonDocument.Parse(petStoreRaw);
 42	                store = PetStoreModel.ParsePetStore(doc.RootElement);
 43	            }
 44	            catch (JsonException) { }
 45	        }
 46	        var legacySlug = ParseOptionalString(legacySlugRaw);
 47	        store = PetStoreModel.MigrateLegacyPetStore(store, legacySlug is null ? null : new LegacyPet(legacySlug, legacySlug));
 48	        if (store.Instances.Count > 0) hadData = true;
 49	
 50	        // 2. 养成状态：legacy slug → 首个实例 id（对齐 care 迁移语义）
 51	        var instanceId = store.SelectedId ?? store.Instances.FirstOrDefault()?.Id;
 52	        if (instanceId is not null && legacySlug is not null && legacySlug != instanceId)
 53	        {
 54	            care = CareStoreModel.MigrateLegacyCareState(care, legacySlug, instanceId);
 55	        }
 56	        if (care.Count > 0) hadData = true;
 57	
 58	        return new TauriMigrationResult(store, care, hadData);
 59	    }
 60	
 61	    private static string? ReadString(JsonElement root, string key)
 62	        => root.TryGetProperty(key, out var value) && value.ValueKind == JsonValueKind.String
 63	            ? value.GetString()
 64	            : null;
 65	
 66	    /// <summary>localStorage 值可能是 JSON 字符串（含引号），也可能是裸字符串。</summary>
 67	    private static string? ParseOptionalString(string? raw)
 68	    {
 69	        if (raw is null) return null;
 70	        var trimmed = raw.Trim();
 71	        if (trimmed.Length >= 2 && trimmed.StartsWith('"') && trimmed.EndsWith('"'))
 72	        {
 73	            try
 74	            {
 75	                return JsonSerializer.Deserialize<string>(trimmed);
 76	            }
 77	            catch (JsonException) { }
 78	        }
 79	        return trimmed;
 80	    }
 81	
 82	    private static Dictionary<string, CareState> ParseCare(string? raw)
 83	    {
 84	        if (raw is null) return [];
 85	        try
 86	        {
 87	            using var doc = JsonDocument.Parse(raw);
 88	            var result = new Dictionary<string, CareState>();
 89	            foreach (var property in doc.RootElement.EnumerateObject())
 90	            {
 91	                var state = property.Value.Deserialize<CareState>(CareJsonOptions);
 92	                if (state is not null) result[property.Name] = state;
 93	            }
 94	            return result;
 95	        }
 96	        catch (JsonException)
 97	        {
 98	            return [];
 99	        }
100	    }
101	
102	    private static readonly JsonSerializerOptions CareJsonOptions = new()
103	    {
104	        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
105	        PropertyNameCaseInsensitive = true,
106	    };
107	}

