 1	using System.Text.Json;
 2	using DesktopPet.Core.Care;
 3	using DesktopPet.Core.Pets;
 4	using DesktopPet.Core.Storage;
 5	using Xunit;
 6	
 7	namespace DesktopPet.Core.Tests;
 8	
 9	/// <summary>迁移工具测试：Tauri localStorage 导出 → 新版 store + care。</summary>
10	public class TauriMigrationTests
11	{
12	    private static readonly DateTime Now = new(2025, 1, 15, 12, 0, 0);
13	
14	    private static JsonElement ExportJson(string json) => JsonDocument.Parse(json).RootElement;
15	
16	    [Fact]
17	    public void Migrates_LegacySlug_IntoDefaultInstance_WithCareState()
18	    {
19	        var export = ExportJson("""
20	            {
21	              "desktoppet.petSlug": "\"cat\"",
22	              "ap_care": "{\"cat\":{\"xp\":75,\"totalMeals\":3,\"tokenCarry\":0,\"tokensToday\":0,\"mealsToday\":0,\"totalTokens\":0,\"lastFedAt\":null,\"dayKey\":\"2025-01-15\",\"streakDays\":0,\"lastFedDayKey\":null,\"days\":{},\"unlockedAchievements\":[]}}"
23	            }
24	            """);
25	
26	        var result = TauriMigration.Migrate(export, Now);
27	
28	        Assert.True(result.HadData);
29	        Assert.Equal("legacy-pet", result.Store.SelectedId);
30	        Assert.Equal("cat", result.Store.Instances[0].SpriteSlug);
31	        Assert.Equal(75, result.Care["legacy-pet"].Xp);
32	        Assert.Equal(3, result.Care["legacy-pet"].TotalMeals);
33	        Assert.False(result.Care.ContainsKey("cat"));
34	    }
35	
36	    [Fact]
37	    public void Migrates_InstanceStore_WhenPresent()
38	    {
39	        var export = ExportJson("""
40	            {
41	              "desktoppet.petSlug": "\"cat\"",
42	              "ap_pet_instances": "{\"version\":1,\"selectedId\":\"pet-a\",\"instances\":[{\"id\":\"pet-a\",\"name\":\"Miso\",\"spriteSlug\":\"nori-openpets\",\"visible\":true,\"size\":100,\"roamEnabled\":true,\"roamMode\":\"wander\",\"roamSpeed\":5,\"reactsToActivity\":true}]}",
43	              "ap_care": "{\"pet-a\":{\"xp\":120}}"
44	            }
45	            """);
46	
47	        var result = TauriMigration.Migrate(export, Now);
48	
49	        Assert.Equal("pet-a", result.Store.SelectedId);
50	        Assert.Equal("nori-openpets", result.Store.Instances[0].SpriteSlug);
51	        Assert.Equal(120, result.Care["pet-a"].Xp);
52	    }
53	
54	    [Fact]
55	    public void Migrate_EmptyExport_ReturnsEmptyStore()
56	    {
57	        var result = TauriMigration.Migrate(ExportJson("{}"), Now);
58	
59	        Assert.False(result.HadData);
60	        Assert.Empty(result.Store.Instances);
61	        Assert.Empty(result.Care);
62	    }
63	
64	    [Fact]
65	    public void Migrate_HandlesMalformedCare()
66	    {
67	        var export = ExportJson("""{"ap_care": "not json", "desktoppet.petSlug": "\"cat\""}""");
68	
69	        var result = TauriMigration.Migrate(export, Now);
70	
71	        Assert.Empty(result.Care);
72	        Assert.Equal("legacy-pet", result.Store.SelectedId);
73	    }
74	}

